-- LEGIT OS - minimal Hyprland configuration (Lua format, Hyprland >= 0.57).
--
-- This file exists so Hyprland does not display its "autogenerated config"
-- banner. It only sets the wallpaper and a few essential keybinds; users are
-- expected to bring their own dotfiles and may edit or replace this file.

hl.monitor({ output = "", mode = "preferred", position = "auto", scale = 1 })

hl.env("XCURSOR_SIZE", "24")

hl.on("hyprland.start", function()
    hl.exec_cmd("swaybg -i /usr/share/backgrounds/legit/ocean-balcony.jpeg -m fill")
end)

local terminal = "kitty"

-- Essentials
hl.bind("CTRL + ALT + T",    hl.dsp.exec_cmd(terminal))
hl.bind("SUPER + Return",    hl.dsp.exec_cmd(terminal))
hl.bind("SUPER + Q",         hl.dsp.window.close())
hl.bind("SUPER + F",         hl.dsp.window.fullscreen({ mode = "fullscreen" }))
hl.bind("SUPER + T",         hl.dsp.window.float({ action = "toggle" }))

-- Alt-Tab style window cycling
hl.bind("ALT + Tab",         hl.dsp.window.cycle_next())
hl.bind("ALT + SHIFT + Tab", hl.dsp.window.cycle_next({ next = false }))

-- Workspaces 1-5
for i = 1, 5 do
    hl.bind("SUPER + " .. i,         hl.dsp.focus({ workspace = i }))
    hl.bind("SUPER + SHIFT + " .. i, hl.dsp.window.move({ workspace = i }))
end

-- Screenshots
hl.bind("PRINT", hl.dsp.exec_cmd("mkdir -p ~/Pictures && grim ~/Pictures/legit-shot-$(date +%s).png"))
